for page in pages:
    text=Path(page).read_text(encoding='utf-8', errors='replace')
    p=P(); p.feed(text)
    dup={k:v for k,v in p.ids.items() if v>1}
    missing=[]
    for href in p.hrefs:
        if href.startswith(('http://','https://','mailto:','tel:','#')): continue
