    def handle_starttag(self, tag, attrs):
        ad=dict(attrs)
        if 'id' in ad: self.ids[ad['id']]=self.ids.get(ad['id'],0)+1
        if 'style' in ad: self.inline_style=True
        if tag=='a' and ad.get('href'): self.hrefs.append(ad['href'])
