   556	        function compareRows(a, b, sortValue) {
   557	          var aTitle = normalizeText(getRowTitle(a));
   558	          var bTitle = normalizeText(getRowTitle(b));
   559	          var aUpdated = parseDateValue(a.dataset.updated);
   560	          var bUpdated = parseDateValue(b.dataset.updated);
   561	          var aDeadline = parseDateValue(a.dataset.deadline);
   562	          var bDeadline = parseDateValue(b.dataset.deadline);
   563	          var aApplications = parseInteger(a.dataset.applications);
   564	          var bApplications = parseInteger(b.dataset.applications);
   565	
   566	          if (sortValue === 'deadline-asc') {
   567	            if (aDeadline && bDeadline) return aDeadline - bDeadline || bUpdated - aUpdated;
   568	            if (!aDeadline && bDeadline) return 1;
   569	            if (aDeadline && !bDeadline) return -1;
   570	            return bUpdated - aUpdated;
   571	          }
   572	
   573	          if (sortValue === 'applications-desc') {
   574	            return bApplications - aApplications || bUpdated - aUpdated || aTitle.localeCompare(bTitle, 'vi');
   575	          }
   576	
   577	          if (sortValue === 'title-asc') {
   578	            return aTitle.localeCompare(bTitle, 'vi') || bUpdated - aUpdated;
